const { clamp } = require('../src/clamp');

test('below the range returns min', () => { expect(clamp(-5, 0, 10)).toBe(0); });
test('above the range returns max', () => { expect(clamp(15, 0, 10)).toBe(10); });
test('inside the range returns n', () => { expect(clamp(5, 0, 10)).toBe(5); });
test('boundaries are unchanged', () => { expect(clamp(0, 0, 10)).toBe(0); expect(clamp(10, 0, 10)).toBe(10); });
